use super::{
    CHANGED, MISSING, Verdict, absent, direct_origin, generator, groups_hashed, supports_check,
    unproven_by_poetry, verdict,
};
use camino::Utf8Path;
use color_eyre::eyre;
use cooldown_core::{CoreError, ToolTermination};
use indoc::indoc;
use toml::Table;

/// The lock Poetry 2.5.1 wrote for a project pinning `six==1.16.0`, hashes elided.
const LOCK: &str = indoc! {r#"
    # This file is automatically @generated by Poetry 2.5.1 and should not be changed by hand.

    [[package]]
    name = "six"
    version = "1.16.0"
    description = "Python 2 and 3 compatibility utilities"
    optional = false
    python-versions = ">=2.7, !=3.0.*, !=3.1.*, !=3.2.*"
    groups = ["main"]
    files = []

    [metadata]
    lock-version = "2.1"
    python-versions = ">=3.9"
    content-hash = "6090832d9210b44f749ed79c41d73f2be7e01d2168caa6ed308e4fd47067602a"
"#};

const MANIFEST: &str = indoc! {r#"
    [project]
    name = "demo"
    version = "0.1.0"
    requires-python = ">=3.9"
    dependencies = ["six==1.16.0"]

    [tool.poetry]
    package-mode = false
"#};

/// [`LOCK`] with its packages emptied by hand, which leaves the content hash intact.
fn emptied_lock() -> String {
    let (generated, _) = LOCK.split_once('\n').expect("generator comment");
    let metadata = LOCK.find("[metadata]").expect("metadata table");
    format!("{generated}\npackage = []\n\n{}", &LOCK[metadata..])
}

fn table(document: &str) -> Table {
    toml::from_str(document).expect("TOML document")
}

/// Only a stable Poetry at or above the floor, printed in the current spelling, qualifies.
#[test]
fn only_a_stable_poetry_2_3_or_newer_qualifies() {
    // Supported
    assert!(supports_check("Poetry (version 2.5.1)\n"));
    assert!(supports_check("Poetry (version 2.3.0)\r\n"));
    assert!(supports_check("Poetry (version 2.3)"));
    assert!(supports_check("Poetry (version 3.0.0.post1)"));

    // Too old, a prerelease, the old spelling, or unparsable
    assert!(!supports_check("Poetry (version 2.2.1)"));
    assert!(!supports_check("Poetry (version 2.3.0rc1)"));
    assert!(!supports_check("Poetry (version 2.3.0.dev0)"));
    assert!(!supports_check("Poetry version 1.1.15"));
    assert!(!supports_check("Poetry (version banana)"));
    assert!(!supports_check(
        "Poetry (version 2.5.1)\nPoetry (version 2.5.1)"
    ));
    assert!(!supports_check(""));
}

/// A refusal is stale only as Poetry's sole output after exit 1; anything beside it, any other
/// exit, or any other output is a failure, while exit 0 passes.
#[test]
fn only_a_standalone_refusal_reads_as_stale() {
    let exit = ToolTermination::ExitCode;

    // Passed
    assert_eq!(verdict(exit(0), "All set!\n", ""), Verdict::Passed);

    // The two refusals, standalone, through CRLF and trailing whitespace
    assert_eq!(
        verdict(exit(1), "", &format!("{CHANGED}\n")),
        Verdict::Changed
    );
    assert_eq!(
        verdict(exit(1), "\r\n", &format!("{CHANGED}  \r\n")),
        Verdict::Changed
    );
    assert_eq!(
        verdict(exit(1), "", &format!("{MISSING}\n")),
        Verdict::Missing
    );

    // A refusal mixed with a strict-mode warning or an invalid configuration
    let warned = format!(
        "{CHANGED}\nWarning: [project.name] and [tool.poetry.name] are both set. The latter will \
         be ignored.\n"
    );
    assert_eq!(verdict(exit(1), "", &warned), Verdict::Failed);
    let invalid = indoc! {"

        The Poetry configuration is invalid:
          - Additional properties are not allowed ('foo' was unexpected)

    "};
    assert_eq!(verdict(exit(1), "", invalid), Verdict::Failed);
    assert_eq!(
        verdict(exit(1), "", &format!("{invalid}{CHANGED}\n")),
        Verdict::Failed
    );

    // A refusal under another exit, quoted in a longer line, or with nothing printed
    assert_eq!(verdict(exit(2), "", CHANGED), Verdict::Failed);
    assert_eq!(
        verdict(ToolTermination::Signal(9), "", CHANGED),
        Verdict::Failed
    );
    assert_eq!(
        verdict(exit(1), "", &format!("plugin: {CHANGED}")),
        Verdict::Failed
    );
    assert_eq!(verdict(exit(1), "", ""), Verdict::Failed);
}

/// Only a missing entry is an absent lock: a dangling link, which Poetry also reports as missing,
/// is present.
#[test]
fn a_lock_is_absent_only_when_nothing_is_there() -> eyre::Result<()> {
    let directory = tempfile::tempdir()?;
    let root = Utf8Path::from_path(directory.path())
        .ok_or_else(|| eyre::eyre!("temporary path is not UTF-8"))?;
    assert!(absent(&root.join("poetry.lock")));

    std::fs::write(root.join("poetry.lock"), LOCK)?;
    assert!(!absent(&root.join("poetry.lock")));

    #[cfg(unix)]
    {
        std::os::unix::fs::symlink(root.join("nowhere"), root.join("dangling.lock"))?;
        assert!(!absent(&root.join("dangling.lock")));
    }
    Ok(())
}

/// Poetry 2.3 and newer compare an older lock without `[dependency-groups]`, so a lock is proven
/// only when its generator hashed them as the checker compares them, or no group exists.
#[test]
fn dependency_groups_are_proven_only_where_the_generator_hashed_them() {
    // Poetry 2.3 and newer hash the groups
    assert!(groups_hashed(Some("2.3.0"), Some("2.1"), true));
    assert!(groups_hashed(Some("2.5.1"), None, true));

    // Poetry 2.2 resolved the groups without hashing them
    assert!(!groups_hashed(Some("2.2.1"), Some("2.1"), false));
    assert!(!groups_hashed(Some("2.3.0rc1"), Some("2.1"), false));

    // Older Poetry ignored the groups
    assert!(groups_hashed(Some("2.1.4"), Some("2.1"), false));
    assert!(groups_hashed(Some("1.8.5"), Some("2.0"), false));
    assert!(!groups_hashed(Some("2.1.4"), Some("2.1"), true));

    // No readable generator: only a pre-2.1 lock without groups
    assert!(groups_hashed(None, Some("2.0"), false));
    assert!(groups_hashed(Some("banana"), Some("1.1"), false));
    assert!(!groups_hashed(None, Some("2.0"), true));
    assert!(!groups_hashed(None, Some("2.1"), false));
    assert!(!groups_hashed(None, None, false));
    assert!(!groups_hashed(None, Some("banana"), false));
}

/// The generator is the version on the lock's opening comment line only.
#[test]
fn the_generator_is_read_from_the_opening_comment() {
    assert_eq!(generator(LOCK), Some("2.5.1"));
    let (_, headless) = LOCK.split_once('\n').expect("generator comment");
    assert_eq!(generator(headless), None);
    assert_eq!(generator(&format!("\n{LOCK}")), None);
}

/// A URL, git, or path origin anywhere in the manifest's declarations, the lock's dependency
/// edges, or a locked package's source is a direct origin; a registry or named index is not.
#[test]
fn direct_origins_are_found_wherever_they_are_declared() {
    let lock = table(LOCK);
    let found = |manifest: &str| direct_origin(&table(manifest), &lock);

    // Registry declarations, a named index, and an `@` only inside a marker
    assert_eq!(found(MANIFEST), None);
    assert_eq!(
        found(indoc! {r#"
            [project]
            name = "demo"
            dependencies = ['six==1.16.0; platform_release == "5.0@x"']

            [tool.poetry.dependencies]
            python = ">=3.9"
            requests = { version = "^2.28", source = "corp" }
        "#}),
        None
    );

    // Poetry tables: main, legacy development, group, and multiple constraints
    for manifest in [
        indoc! {r#"
            [tool.poetry.dependencies]
            six = { git = "https://github.com/benjaminp/six.git", tag = "1.16.0" }
        "#},
        indoc! {r#"
            [tool.poetry.dev-dependencies]
            six = { url = "https://example.com/six-1.16.0-py2.py3-none-any.whl" }
        "#},
        indoc! {r#"
            [tool.poetry.group.dev.dependencies]
            local = { path = "../local", develop = true }
        "#},
        indoc! {r#"
            [tool.poetry.dependencies]
            six = [
                { version = "1.16.0", python = "<3.12" },
                { path = "../six", python = ">=3.12" },
            ]
        "#},
    ] {
        assert!(found(manifest).is_some(), "{manifest}");
    }

    // PEP 508 direct references: main, an extra, and a dependency group
    for manifest in [
        indoc! {r#"
            [project]
            dependencies = ["six @ https://example.com/six-1.16.0-py2.py3-none-any.whl"]
        "#},
        indoc! {r#"
            [project.optional-dependencies]
            extra = ["six @ git+https://github.com/benjaminp/six.git@1.16.0"]
        "#},
        indoc! {r#"
            [dependency-groups]
            dev = ["local @ file:///srv/local"]
        "#},
    ] {
        let reason = found(manifest).expect("a direct reference");
        assert!(reason.contains("pyproject.toml"), "{reason}");
    }

    // The lock: a package source of each direct kind, and a dependency edge
    for kind in ["url", "git", "directory", "file"] {
        let lock = table(&LOCK.replace(
            "files = []",
            &format!("files = []\n\n[package.source]\ntype = \"{kind}\"\nurl = \"x\""),
        ));
        let reason = direct_origin(&table(MANIFEST), &lock).expect(kind);
        assert!(
            reason.contains("poetry.lock") && reason.contains("`six`"),
            "{reason}"
        );
    }
    let legacy = table(&LOCK.replace(
        "files = []",
        "files = []\n\n[package.source]\ntype = \"legacy\"\nurl = \"https://pypi.corp.example/simple\"\nreference = \"corp\"",
    ));
    assert_eq!(direct_origin(&table(MANIFEST), &legacy), None);
    let edge = table(&LOCK.replace(
        "files = []",
        "files = []\n\n[package.dependencies]\nlocal = { path = \"../local\", develop = true }",
    ));
    let reason = direct_origin(&table(MANIFEST), &edge).expect("a direct edge");
    assert!(reason.contains("`local`"), "{reason}");
}

/// An emptied lock is unproven while anything declares a package, but not for a manifest that
/// declares only its Python constraint.
#[test]
fn an_emptied_lock_is_unproven_while_packages_are_declared() -> eyre::Result<()> {
    let lock = emptied_lock();
    for manifest in [
        MANIFEST,
        indoc! {r#"
            [tool.poetry.dependencies]
            python = ">=3.9"
            six = "1.16.0"
        "#},
        indoc! {r#"
            [tool.poetry.group.dev.dependencies]
            six = "1.16.0"
        "#},
        indoc! {r#"
            [project.optional-dependencies]
            extra = ["six==1.16.0"]
        "#},
        indoc! {r#"
            [dependency-groups]
            dev = ["six==1.16.0"]
        "#},
    ] {
        let reason = unproven_by_poetry(&lock, manifest)?;
        assert!(
            reason
                .as_deref()
                .is_some_and(|reason| reason.contains("lists no packages")),
            "{manifest}: {reason:?}"
        );
    }

    // The Python constraint alone declares no package
    let python_only = indoc! {r#"
        [tool.poetry.dependencies]
        python = ">=3.9"
    "#};
    assert_eq!(unproven_by_poetry(&lock, python_only)?, None);
    Ok(())
}

/// A lock Poetry 2.5.1 wrote for a registry pin is proven, while `project.dynamic`, an older
/// generator beside dependency groups, or a lock that is not one is not.
#[test]
fn unproven_by_poetry_reads_the_lock_and_the_manifest() -> eyre::Result<()> {
    assert_eq!(unproven_by_poetry(LOCK, MANIFEST)?, None);

    let dynamic = MANIFEST.replace("[tool.poetry]", "dynamic = [\"version\"]\n\n[tool.poetry]");
    let reason = unproven_by_poetry(LOCK, &dynamic)?;
    assert!(
        reason
            .as_deref()
            .is_some_and(|reason| reason.contains("project.dynamic")),
        "{reason:?}"
    );

    let grouped = format!("{MANIFEST}\n[dependency-groups]\ndev = []\n");
    let older = LOCK.replace("Poetry 2.5.1", "Poetry 2.1.4");
    let reason = unproven_by_poetry(&older, &grouped)?;
    assert!(
        reason
            .as_deref()
            .is_some_and(|reason| reason.contains("dependency-groups")),
        "{reason:?}"
    );
    assert_eq!(unproven_by_poetry(&older, MANIFEST)?, None);

    // A lock without its packages, or one that is not TOML, is an error rather than empty
    let unlisted = LOCK[LOCK.find("[metadata]").expect("metadata")..].to_string();
    assert!(matches!(
        unproven_by_poetry(&unlisted, MANIFEST),
        Err(CoreError::LockUnreadable(_))
    ));
    assert!(matches!(
        unproven_by_poetry("[[package]\n", MANIFEST),
        Err(CoreError::LockUnreadable(_))
    ));
    Ok(())
}
